#include "engine.hpp"
#include <iostream>
#include <cmath>
#include <map>
using namespace uaa;
void check(bool b,const char* text){if(!b)throw std::runtime_error(text);}
int main(int argc,char** argv){try{
 check(argc==3,"Expected data and temporary directory");Engine e(argv[1],argv[2]);e.createBase("Test",50,14);auto money=e.state["money"].get<long long>();e.ensureHouston();check(e.astronautCapacity()==8&&e.state["spaceHousing"].size()==2,"HTML provides two initial homes / eight crew places");check(e.state["money"].get<long long>()==money-480000,"HTML charges initial homes once");
 std::map<std::string,std::pair<int,int>> positions={{"command",{0,4}},{"power",{3,2}},{"datacenter",{0,2}},{"crewTraining",{3,4}}};int houses=0;bool occupied[10][10]={};for(const auto& b:e.state["houstonBuildings"]){std::string id=b["id"];int x=b["x"],y=b["y"];if(id=="residential"){check(x==(houses?2:0)&&y==0,"Initial home coordinates match HTML");++houses;}else check(positions.at(id)==std::pair<int,int>{x,y},"Houston core coordinates match HTML");auto [w,h]=e.footprint(id);for(int row=y;row<y+h;++row)for(int col=x;col<x+w;++col){check(row<10&&col<10&&!occupied[row][col],"Houston footprint overlap");occupied[row][col]=true;}}
 check(houses==2&&e.state["houstonBuildings"].size()==6,"Correct six-object Houston layout");auto before=e.state;e.ensureHouston();check(before==e.state,"Opening Houston repeatedly never duplicates buildings or charges");check(!e.hireAstronaut(0).ok&&e.state==before,"Recruitment requires a lease and fails atomically");check(e.rentLocation("nasa").ok,"Rent Houston");for(int i=0;i<8;++i)check(e.hireAstronaut(i%24).ok,"Recruit eight crew into built-in housing");before=e.state;check(!e.hireAstronaut(0).ok&&e.state==before,"Full housing rejects ninth astronaut visibly without changes");check(e.buildSpaceHousing().ok&&e.astronautCapacity()==8,"Construction does not prematurely add capacity");check(e.state["houstonBuildings"].back()["x"]==5&&e.state["houstonBuildings"].back()["y"]==0,"Third home uses HTML slot");e.advance(72);check(e.astronautCapacity()==12&&e.hireAstronaut(0).ok,"Finished home allows ninth recruit");e.save(1);Engine loaded(argv[1],argv[2]);check(loaded.load(1).ok,"Houston save loads");money=loaded.state["money"];loaded.ensureHouston();check(loaded.state["money"]==money&&loaded.astronautCapacity()==12&&loaded.state["astronauts"].size()==9,"Save/load preserves Houston, capacity and crew without extra charge");
 Engine legacy(argv[1],fs::path(argv[2])/"legacy");legacy.ensureLocations();legacy.state["spaceHousing"].push_back(72.);money=legacy.state["money"];legacy.ensureHouston();check(legacy.state["spaceHousing"].size()==2&&legacy.state["spaceHousing"][0]==72.&&legacy.state["money"].get<long long>()==money-240000,"Old native housing is preserved; only missing reference home is added");
 for(const std::string key:{"esa","roscosmos"}){Engine center(argv[1],fs::path(argv[2])/key);auto initialMoney=center.state["money"].get<long long>();center.ensureSpaceBase(key);auto canonical=readJson(fs::path(argv[1])/"space/control-layouts.json")[key]["buildings"];check(center.state["spaceBases"][key]==canonical,"ESA/Roscosmos preserve exact HTML layout");int homes=0,warehouses=0;bool used[10][10]={};for(const auto& b:center.state["spaceBases"][key]){if(b["id"]=="residential")++homes;if(b["id"]=="storage")++warehouses;auto [w,h]=center.footprint(b["id"]);for(int y=b["y"];y<b["y"].get<int>()+h;++y)for(int x=b["x"];x<b["x"].get<int>()+w;++x){check(x<10&&y<10&&!used[y][x],"Control base buildings must not overlap");used[y][x]=true;}}check(homes==2&&warehouses==(key=="esa"?6:4),"Reference housing/storage counts");check(center.state["money"].get<long long>()==initialMoney-(key=="roscosmos"?480000:0),"Reference housing cost");check(center.staffCapacity("research")==0,"Unleased control buildings do not provide workplaces");check(center.rentLocation(key).ok,"Rent control center");check(center.staffCapacity("research")==25&&center.staffCapacity("workshop")==25,"Leased laboratories and workshops provide real workplaces");check(center.storageCapacity()["capacity"]==(key=="esa"?240:160),"Leased warehouses contribute real pallet capacity");auto snapshot=center.state;center.ensureSpaceBase(key);check(center.state==snapshot,"Control layout initializes only once");center.save(1);Engine restored(argv[1],fs::path(argv[2])/key);check(restored.load(1).ok,"ESA/Roscosmos layout survives save/load");restored.ensureSpaceBase(key);check(restored.state["money"]==snapshot["money"]&&restored.state["spaceBases"]==snapshot["spaceBases"],"Restored control layout does not charge twice");}
 Engine expiry(argv[1],fs::path(argv[2])/"expiry");expiry.createBase("Expiry",50,14);expiry.ensureSpaceBase("esa");expiry.rentLocation("esa");expiry.state["leases"]["esa"]=1.;expiry.startResearch("research_basic_lab");expiry.state["personnel"]=Json::array();for(int i=0;i<30;++i){expiry.state["personnel"].push_back(expiry.makeCandidate("scientist",0));check(expiry.assignScientist("research_basic_lab",i,true).ok,"Use additional leased workplaces");}expiry.advance(2);check(expiry.researchTeam("research_basic_lab").size()==25&&expiry.staffCapacity("research")==25,"Expired lease releases only excess workers");auto quote=expiry.researchQuote("research_basic_lab");double expected=55./(quote["hours"].get<double>()*quote["scientists"].get<int>());check(std::abs(expiry.state["research"]["research_basic_lab"].get<double>()-expected)<1e-8,"Time jump applies leased workplaces only before lease expiry");
 std::cout<<"PASS: reference Houston positions/footprints, two homes, eight crew, one-time cost, lease, full capacity, construction, saved campaign and old-save migration\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
